		e.BY = int32(client.Uint32(data[l : l+4]))
		l += 4
		e.WX = int32(client.Uint32(data[l : l+4]))
		l += 4
		e.WY = int32(client.Uint32(data[l : l+4]))
		l += 4

		i.primariesHandler(e)
